"""Sidebar menu and panel notices for Admin V2 shell."""

from __future__ import annotations

from flask_babel import get_locale
from flask_babel import gettext as _

from flask import g
from hiddifypanel import hutils
from hiddifypanel.hutils.flask import get_proxy_stats_url, hurl_for
from hiddifypanel.models import ConfigEnum, Domain, User, hconfig
from hiddifypanel.panel import hiddify


def _item(label: str, url: str, icon: str, *, target: str = "_self", badge: str | None = None) -> dict:
    row: dict = {"label": label, "url": url, "icon": icon, "target": target}
    if badge:
        row["badge"] = badge
    return row


def _post_action(label: str, url: str, icon: str) -> dict:
    """System action: the endpoint only accepts POST, so the shell confirms and submits a form."""
    row = _item(label, url, icon)
    row["method"] = "post"
    row["confirm"] = _("Are you sure you want to do this action?")
    return row


def _wiki_support_url() -> str:
    if get_locale() == "fa":
        return "https://github.com/hiddify/hiddify-manager/wiki/%D9%87%D9%85%D9%87-%D8%A2%D9%85%D9%88%D8%B2%D8%B4%E2%80%8C%D9%87%D8%A7-%D9%88-%D9%88%DB%8C%D8%AF%D8%A6%D9%88%D9%87%D8%A7"
    return "https://github.com/hiddify/hiddify-manager/wiki/All-tutorials-and-videos"


def _build_admin_v2_menu_stock() -> list[dict]:
    """Grouped legacy panel menu (full-page links). V2 routes are added in the frontend."""
    groups: list[dict] = []

    home_label = _("Parent Panel") if hutils.node.is_parent() else _("admin.menu.home")
    master_items = [
        # _item(home_label, hurl_for("admin.Dashboard:index"), "pi pi-fw pi-home"),
    ]
    if hconfig(ConfigEnum.parent_panel):
        master_items.extend(
            [
                _item(_("admin.menu.user"), hconfig(ConfigEnum.parent_panel) + "admin/user/", "pi pi-fw pi-users"),
                _item(_("Admins"), hconfig(ConfigEnum.parent_panel) + "admin/adminuser/", "pi pi-fw pi-user-edit"),
            ]
        )
    else:
        master_items.extend(
            [
                _item(_("admin.menu.user"), hurl_for("flask.user.index_view"), "pi pi-fw pi-users"),
                _item(_("Admins"), hurl_for("flask.adminuser.index_view"), "pi pi-fw pi-user-edit"),
            ]
        )
    if hutils.node.is_parent():
        master_items.append(
            _item(_("Nodes"), hurl_for("flask.node.index_view"), "pi pi-fw pi-server"),
        )
    groups.append(
        {
            "label": _("master.page-title"),
            "items": master_items,
        }
    )

    if g.account.mode != "agent":
        settings_items = [
            _item(_("admin.menu.domain"), hurl_for("flask.domain.index_view"), "pi pi-fw pi-link"),
            _item(_("admin.menu.proxy"), hurl_for("admin.ProxyAdmin:index"), "pi pi-fw pi-sitemap"),
        ]
        if g.account.mode == "super_admin":
            settings_items.extend(
                [
                    _item(_("admin.menu.config"), hurl_for("admin.SettingAdmin:index"), "pi pi-fw pi-cog"),
                    _item(_("Backup"), hurl_for("admin.Backup:index"), "pi pi-fw pi-save"),
                ]
            )
        if hconfig(ConfigEnum.telegram_bot_token) and getattr(g, "bot", None):
            settings_items.append(
                _item(
                    _("Telegram Bot"),
                    f"tg://resolve?domain={g.bot.username}&start=admin_{g.account.uuid}",
                    "pi pi-fw pi-telegram",
                ),
            )
        if g.account.mode == "super_admin":
            settings_items.append(
                _item(_("admin.menu.api"), hurl_for("openapi.docs"), "pi pi-fw pi-code"),
            )
            settings_items.append(
                _item(_("admin.menu.proxy_stats"), get_proxy_stats_url(), "pi pi-fw pi-chart-bar"),
            )
        groups.append({"label": _("admin.menu.config"), "items": settings_items})

    if g.account.mode == "super_admin":
        groups.append(
            {
                "label": _("admin.actions.title"),
                "items": [
                    _item(_("admin.actions.status"), hurl_for("admin.Actions:status"), "pi pi-fw pi-chart-line"),
                    _item(_("admin.actions.viewlogs"), hurl_for("admin.Actions:viewlogs"), "pi pi-fw pi-inbox"),
                    _post_action(_("admin.actions.apply_configs"), hurl_for("admin.Actions:apply_configs"), "pi pi-fw pi-bolt"),
                    _post_action(_("admin.actions.update"), hurl_for("admin.Actions:update"), "pi pi-fw pi-upload"),
                    _post_action(_("admin.actions.reinstall"), hurl_for("admin.Actions:reinstall"), "pi pi-fw pi-refresh"),
                    _post_action(_("admin.actions.reset"), hurl_for("admin.Actions:reset"), "pi pi-fw pi-power-off"),
                ],
            }
        )

    groups.append(
        {
            "label": _("admin.menu.support"),
            "items": [
                _item(_("admin.menu.support"), _wiki_support_url(), "pi pi-fw pi-question-circle", target="_blank"),
                _item(
                    _("Bug"),
                    hutils.github_issue.generate_github_issue_link_for_admin_sidebar(),
                    "pi pi-fw pi-exclamation-circle",
                    target="_blank",
                ),
                _item(_("Donation.title"), hurl_for("admin.Dashboard:index"), "pi pi-fw pi-heart"),
            ],
        }
    )

    return groups


def build_admin_v2_notices() -> list[dict]:
    """Panel warnings mirrored from the classic dashboard (no flash session)."""
    notices: list[dict] = []

    if hutils.utils.is_panel_outdated():
        notices.append(
            {
                "severity": "warn",
                "summary": _("outdated_panel"),
                "toast": True,
            }
        )

    def_user = None if len(User.query.all()) > 1 else User.query.filter(User.name == "default").first()
    domains = Domain.get_domains()
    sslip_domains = [d.domain for d in domains if "sslip.io" in d.domain]

    if def_user and sslip_domains:
        quick_setup = hurl_for("admin.QuickSetup:index")
        notices.append(
            {
                "severity": "warn",
                "summary": _("admin.incomplete_setup_warning", quick_setup=quick_setup),
            }
        )
        if hutils.node.is_parent():
            notices.append(
                {
                    "severity": "error",
                    "summary": _(
                        "Please understand that parent panel is under test and the plan and the condition of use maybe change at anytime.",
                    ),
                }
            )
    elif sslip_domains:
        notices.append(
            {
                "severity": "warn",
                "summary": _(
                    "It seems that you are using default domain (%(domain)s) which is not recommended.",
                    domain=sslip_domains[0],
                ),
            }
        )
        if hutils.node.is_parent():
            notices.append(
                {
                    "severity": "error",
                    "summary": _(
                        "Please understand that parent panel is under test and the plan and the condition of use maybe change at anytime.",
                    ),
                }
            )
    elif def_user:
        d = domains[0] if domains else None
        if d:
            notices.append(
                {
                    "severity": "info",
                    "summary": _(
                        "admin.no_user_warning",
                        default_link=hiddify.get_html_user_link(def_user, d),
                    ),
                }
            )

    if hutils.network.is_ssh_password_authentication_enabled():
        notices.append(
            {
                "severity": "warn",
                "summary": "Сервер уязвим для подбора пароля: в SSH включён вход по паролю. Для защиты перейдите на вход по ключу и отключите парольную аутентификацию.",
            }
        )

    return notices


# ---------------------------------------------------------------------------------------------------------------- our own grouped menu (CP-16, text proposal)
def _link(label: str, endpoint: str, icon: str, **kw):
    """an item for an endpoint that may not exist on this panel (a layer that is not installed): None instead of an error"""
    try:
        return _item(label, hurl_for(endpoint, **kw), icon)
    except Exception:
        return None


def build_admin_v2_menu_ru() -> list[dict]:
    """Groups and Russian names for the whole panel: the old pages that exist here, in a RemnaWave-like order. Only text: the pages themselves are the old ones."""
    me = g.account.mode
    groups: list[dict] = []

    def group(label, items):
        items = [i for i in items if i]
        if items:
            groups.append({"label": label, "items": items})

    group("Управление", [
        _link("Пользователи", "flask.user.index_view", "pi pi-fw pi-users"),
        _link("Администраторы", "flask.adminuser.index_view", "pi pi-fw pi-user-edit"),
        _link("Домены", "flask.domain.index_view", "pi pi-fw pi-link") if me != "agent" else None,
        _link("Протоколы", "admin.ProxyAdmin:index", "pi pi-fw pi-sitemap") if me != "agent" else None,
    ])
    if me == "super_admin":
        group("Маршрутизация", [
            _link("Обзор маршрутизации", "admin.RoutingAdmin:index", "pi pi-fw pi-compass"),
            _link("Внешние ноды", "admin.RoutingAdmin:upstream_list", "pi pi-fw pi-server"),
            _link("Локации", "admin.RoutingAdmin:location_list", "pi pi-fw pi-globe"),
            _link("Источники правил", "admin.RoutingAdmin:rule_source_list", "pi pi-fw pi-list"),
        ])
        group("Подписка", [
            _link("Happ / INCY", "admin.RoutingAdmin:happ_page", "pi pi-fw pi-mobile"),
        ])
        group("Безопасность", [
            _link("Анти-шаринг", "admin.AntiShareAdmin:index", "pi pi-fw pi-shield"),
        ])
        group("Бизнес", [
            _link("Тарифы", "flask.plans.index_view", "pi pi-fw pi-credit-card"),
            _link("Telegram-бот", "admin.BusinessAdmin:index", "pi pi-fw pi-send", section="telegram"),
            _link("YooKassa", "admin.BusinessAdmin:index", "pi pi-fw pi-wallet", section="yookassa"),
        ])
        system = [
            _link("Настройки", "admin.SettingAdmin:index", "pi pi-fw pi-cog"),
            _link("Резервные копии", "admin.Backup:index", "pi pi-fw pi-save"),
            _link("Статус сервера", "admin.Actions:status", "pi pi-fw pi-chart-line"),
            _link("Журналы", "admin.Actions:viewlogs", "pi pi-fw pi-inbox"),
        ]
        try:
            system.append(_item("Статистика прокси", get_proxy_stats_url(), "pi pi-fw pi-chart-bar"))
        except Exception:
            pass
        try:
            system.append(_item("API", hurl_for("openapi.docs"), "pi pi-fw pi-code"))
        except Exception:
            pass
        for label, endpoint, icon in (("Применить конфигурацию", "admin.Actions:apply_configs", "pi pi-fw pi-bolt"), ("Обновить панель", "admin.Actions:update", "pi pi-fw pi-upload"),
                                      ("Переустановить", "admin.Actions:reinstall", "pi pi-fw pi-refresh"), ("Перезагрузить сервер", "admin.Actions:reset", "pi pi-fw pi-power-off")):
            try:
                system.append(_post_action(label, hurl_for(endpoint), icon))
            except Exception:
                pass
        group("Система", system)
    group("Помощь", [
        _item("Помощь", _wiki_support_url(), "pi pi-fw pi-question-circle", target="_blank"),
        _item("Ошибки и предложения", hutils.github_issue.generate_github_issue_link_for_admin_sidebar(), "pi pi-fw pi-exclamation-circle", target="_blank"),
    ])
    return groups


_PI_TO_FA = {
    "pi-users": "fa-solid fa-users", "pi-user-edit": "fa-solid fa-user-gear", "pi-link": "fa-solid fa-link", "pi-sitemap": "fa-solid fa-sitemap", "pi-compass": "fa-solid fa-compass",
    "pi-server": "fa-solid fa-server", "pi-globe": "fa-solid fa-globe", "pi-list": "fa-solid fa-list", "pi-mobile": "fa-solid fa-mobile-screen", "pi-shield": "fa-solid fa-shield-halved",
    "pi-credit-card": "fa-solid fa-credit-card", "pi-send": "fa-brands fa-telegram", "pi-wallet": "fa-solid fa-wallet", "pi-cog": "fa-solid fa-gear", "pi-save": "fa-solid fa-floppy-disk",
    "pi-chart-line": "fa-solid fa-signal", "pi-inbox": "fa-solid fa-inbox", "pi-chart-bar": "fa-solid fa-chart-column", "pi-code": "fa-solid fa-code", "pi-bolt": "fa-solid fa-bolt",
    "pi-upload": "fa-solid fa-arrow-up-from-bracket", "pi-refresh": "fa-solid fa-rotate", "pi-power-off": "fa-solid fa-power-off", "pi-question-circle": "fa-solid fa-circle-question",
    "pi-exclamation-circle": "fa-solid fa-bug", "pi-home": "fa-solid fa-house",
}


def _with_fa(groups: list[dict]) -> list[dict]:
    """the same groups for the old (Font Awesome) pages: every item also carries `fa`"""
    for grp in groups:
        for it in grp["items"]:
            pi = next((c for c in reversed(str(it.get("icon", "")).split()) if c.startswith("pi-") and c != "pi-fw"), "")
            it["fa"] = _PI_TO_FA.get(pi, "fa-solid fa-circle")
    return groups


def build_admin_v2_menu() -> list[dict]:
    try:
        return _with_fa(build_admin_v2_menu_ru())
    except Exception:                                   # never leave the panel without a menu
        return _build_admin_v2_menu_stock()


def admin_v2_layout_menu() -> dict:
    """for the old pages' sidebar (admin-layout.html): the same groups and the item that matches the current address best (exact, else the longest prefix)"""
    from urllib.parse import urlparse

    from flask import request
    groups = build_admin_v2_menu()

    def tail(p: str) -> str:                               # the first segment is the panel's secret path: the same page can be opened under another one
        parts = p.strip("/").split("/", 1)
        return parts[1].rstrip("/") if len(parts) > 1 else ""

    path = tail(request.path)
    best, best_len = None, -1
    for grp in groups:
        for it in grp["items"]:
            if it.get("method") == "post" or it.get("target") == "_blank":
                continue
            p = tail(urlparse(it["url"]).path)
            if p and (path == p or path.startswith(p + "/")) and len(p) > best_len:
                best, best_len = it["url"], len(p)
    return {"groups": groups, "active": best, "v2_url": hurl_for("admin.admin_v2")}
